        "name": {
          "type": "string",
          "enum": [
            "UniProt"
          ],
          "description": "Controlled identifier provided by the external source, e.g. PATRIC, UniProt"
        },
        "url": {
          "type": "string",
          "description": "Primary URL for the source, e.g. uniprot.org"
        },
        "description": {
          "type": "string",
          "description": "Short description describing the source"
        },
        "citation": {
          "type": "object",
