    "loginEndpoint": {
      "url": "https://example.com/login"
    }
  },
  "authorization_code": {
    "tokenEndpoint": {
      "url": "https://example.com/token"
    },
    "tokenRequestEndpoint": {
      "url": "https://example.com/token",
      "clientIdName": "client_id",
      "clientSecretName": "client_secret"
    }
  }
}
