    "yes_label": {
      "type": "string",
      "minLength": 0,
      "maxLength": 255
    },
    "no_label": {
      "type": "string",
      "minLength": 0,
      "maxLength": 255
    },
    "is_consent": {
      "type": "boolean",
      "description": "If this field relates to acquiring a user's consent, e.g. subscribing to a newsletter, then this field can be used to ensure that consent is tracked."
    }
  },
  "required": [
    "_schema",
    "name"
  ],
  "additionalProperties": false
}

