          "items": {
            "type": "string",
            "format": "topic"
          }
        }
      }
    },
    "flags": {
      "description": "Flags to set/clear depending on the (absence of a) paste mime-type.",
      "type": "array",
      "default": [],
      "items": {
        "type": "object",
        "required": [
          "flag"
        ],
        "properties": {
          "flag": {
            "type": "string",
            "format": "topic"
          },
          "mimeType": {
            "type": [
              "string",
              "null"
            ],
            "default": null
          },
          "condition": {
            "type": [
              "string",
              "null"
            ],
            "default": null,
            "enum": [
              "DIRTY",
              "CREATED",
              "AVAILABLE",
              "EMPTY",
              null
            ]
          }
        }
      }
    }
  }
