            "contentLocations",
            "doorLocations",
            "minimap"
          ],
          "properties": {
            "areaCode": {
              "type": "string"
            },
            "contentLocations": {
              "type": "object",
              "oneOf": [
                {
                  "additionalProperties": false,
                  "required": [
                    "major",
                    "minor"
                  ],
                  "properties": {
                    "major": {
                      "$ref": "#/definitions/directionList"
                    },
                    "minor": {
                      "$ref": "#/definitions/directionList"
                    }
                  }
                },
                {
                  "additionalProperties": false,
                  "required": [
                    "generic"
                  ],
                  "properties": {
                    "generic": {
                      "$ref": "#/definitions/directionList"
                    }
                  }
                }
              ]
            },
            "doorLocations": {
              "$ref": "#/definitions/directionList"
            },
            "minimap": {
              "type": "object",
              "required": [
                "rows",
                "columns",
                "directions"
              ],
              "properties": {
                "rows": {
                  "type": "integer"
                },
                "columns": {
                  "type": "integer"
                },
                "directions": {
                  "type": "object",
                  "propertyNames": {
                    "$ref": "#/definitions/direction"
                  },
                  "additionalProperties": {
                    "type": "array",
                    "minItems": 2,
                    "maxItems": 2,
                    "items": {
                      "type": "integer"
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  },
  "definitions": {
    "direction": {
      "enum": [
        "N",
        "NE",
        "E",
        "SE",
        "S",
        "SW",
        "W",
        "NW"
      ]
